/* ================= Para educadores: BNCC, ODS e referências ================= */
(function(){
  const BNCC = {"EF01CI01": {"texto": "(EF01CI01) Comparar características de diferentes materiais presentes em objetos de uso cotidiano, discutindo sua origem, os modos como são descartados e como podem ser usados de forma mais consciente.", "componente": "Ciências", "ano": "1º ano", "unidade": "Matéria e energia", "objeto": "Características dos materiais", "pagina": "p. 333 (página 335 do arquivo PDF)"}, "EF02CI04": {"texto": "(EF02CI04) Descrever características de plantas e animais (tamanho, forma, cor, fase da vida, local onde se desenvolvem etc.) que fazem parte de seu cotidiano e relacioná-las ao ambiente em que eles vivem.", "componente": "Ciências", "ano": "2º ano", "unidade": "Vida e evolução", "objeto": "Seres vivos no ambiente; Plantas", "pagina": "p. 335 (página 337 do arquivo PDF)"}, "EF02GE04": {"texto": "(EF02GE04) Reconhecer semelhanças e diferenças nos hábitos, nas relações com a natureza e no modo de viver de pessoas em diferentes lugares.", "componente": "Geografia", "ano": "2º ano", "unidade": "Conexões e escalas", "objeto": "Experiências da comunidade no tempo e no espaço", "pagina": "p. 373 (página 375 do arquivo PDF)"}, "EF02GE11": {"texto": "(EF02GE11) Reconhecer a importância do solo e da água para a vida, identificando seus diferentes usos (plantação e extração de materiais, entre outras possibilidades) e os impactos desses usos no cotidiano da cidade e do campo.", "componente": "Geografia", "ano": "2º ano", "unidade": "Natureza, ambientes e qualidade de vida", "objeto": "Os usos dos recursos naturais: solo e água no campo e na cidade", "pagina": "p. 373 (página 375 do arquivo PDF)"}, "EF03CI10": {"texto": "(EF03CI10) Identificar os diferentes usos do solo (plantação e extração de materiais, dentre outras possibilidades), reconhecendo a importância do solo para a agricultura e para a vida.", "componente": "Ciências", "ano": "3º ano", "unidade": "Terra e Universo", "objeto": "Características da Terra; Observação do céu; Usos do solo", "pagina": "p. 337 (página 339 do arquivo PDF)"}, "EF03GE01": {"texto": "(EF03GE01) Identificar e comparar aspectos culturais dos grupos sociais de seus lugares de vivência, seja na cidade, seja no campo.", "componente": "Geografia", "ano": "3º ano", "unidade": "O sujeito e seu lugar no mundo", "objeto": "A cidade e o campo: aproximações e diferenças", "pagina": "p. 375 (página 377 do arquivo PDF)"}, "EF03GE09": {"texto": "(EF03GE09) Investigar os usos dos recursos naturais, com destaque para os usos da água em atividades cotidianas (alimentação, higiene, cultivo de plantas etc.), e discutir os problemas ambientais provocados por esses usos.", "componente": "Geografia", "ano": "3º ano", "unidade": "Natureza, ambientes e qualidade de vida", "objeto": "Impactos das atividades humanas", "pagina": "p. 375 (página 377 do arquivo PDF)"}, "EF03GE10": {"texto": "(EF03GE10) Identificar os cuidados necessários para utilização da água na agricultura e na geração de energia de modo a garantir a manutenção do provimento de água potável.", "componente": "Geografia", "ano": "3º ano", "unidade": "Natureza, ambientes e qualidade de vida", "objeto": "Impactos das atividades humanas", "pagina": "p. 375 (página 377 do arquivo PDF)"}, "EF04CI02": {"texto": "(EF04CI02) Testar e relatar transformações nos materiais do dia a dia quando expostos a diferentes condições (aquecimento, resfriamento, luz e umidade).", "componente": "Ciências", "ano": "4º ano", "unidade": "Matéria e energia", "objeto": "Misturas; Transformações reversíveis e não reversíveis", "pagina": "p. 339 (página 341 do arquivo PDF)"}, "EF04CI04": {"texto": "(EF04CI04) Analisar e construir cadeias alimentares simples, reconhecendo a posição ocupada pelos seres vivos nessas cadeias e o papel do Sol como fonte primária de energia na produção de alimentos.", "componente": "Ciências", "ano": "4º ano", "unidade": "Vida e evolução", "objeto": "Cadeias alimentares simples; Microrganismos", "pagina": "p. 339 (página 341 do arquivo PDF)"}, "EF04GE11": {"texto": "(EF04GE11) Identificar as características das paisagens naturais e antrópicas (relevo, cobertura vegetal, rios etc.) no ambiente em que vive, bem como a ação humana na conservação ou degradação dessas áreas.", "componente": "Geografia", "ano": "4º ano", "unidade": "Natureza, ambientes e qualidade de vida", "objeto": "Conservação e degradação da natureza", "pagina": "p. 377 (página 379 do arquivo PDF)"}, "EF05CI02": {"texto": "(EF05CI02) Aplicar os conhecimentos sobre as mudanças de estado físico da água para explicar o ciclo hidrológico e analisar suas implicações na agricultura, no clima, na geração de energia elétrica, no provimento de água potável e no equilíbrio dos ecossistemas regionais (ou locais).", "componente": "Ciências", "ano": "5º ano", "unidade": "Matéria e energia", "objeto": "Propriedades físicas dos materiais; Ciclo hidrológico; Consumo consciente; Reciclagem", "pagina": "p. 341 (página 343 do arquivo PDF)"}, "EF05CI03": {"texto": "(EF05CI03) Selecionar argumentos que justifiquem a importância da cobertura vegetal para a manutenção do ciclo da água, a conservação dos solos, dos cursos de água e da qualidade do ar atmosférico.", "componente": "Ciências", "ano": "5º ano", "unidade": "Matéria e energia", "objeto": "Propriedades físicas dos materiais; Ciclo hidrológico; Consumo consciente; Reciclagem", "pagina": "p. 341 (página 343 do arquivo PDF)"}, "EF05CI04": {"texto": "(EF05CI04) Identificar os principais usos da água e de outros materiais nas atividades cotidianas para discutir e propor formas sustentáveis de utilização desses recursos.", "componente": "Ciências", "ano": "5º ano", "unidade": "Matéria e energia", "objeto": "Propriedades físicas dos materiais; Ciclo hidrológico; Consumo consciente; Reciclagem", "pagina": "p. 341 (página 343 do arquivo PDF)"}, "EF05CI05": {"texto": "(EF05CI05) Construir propostas coletivas para um consumo mais consciente e criar soluções tecnológicas para o descarte adequado e a reutilização ou reciclagem de materiais consumidos na escola e/ou na vida cotidiana.", "componente": "Ciências", "ano": "5º ano", "unidade": "Matéria e energia", "objeto": "Propriedades físicas dos materiais; Ciclo hidrológico; Consumo consciente; Reciclagem", "pagina": "p. 341 (página 343 do arquivo PDF)"}, "EF05GE11": {"texto": "(EF05GE11) Identificar e descrever problemas ambientais que ocorrem no entorno da escola e da residência (lixões, indústrias poluentes, destruição do patrimônio histórico etc.), propondo soluções (inclusive tecnológicas) para esses problemas.", "componente": "Geografia", "ano": "5º ano", "unidade": "Natureza, ambientes e qualidade de vida", "objeto": "Diferentes tipos de poluição", "pagina": "p. 379 (página 381 do arquivo PDF)"}, "EF06GE04": {"texto": "(EF06GE04) Descrever o ciclo da água, comparando o escoamento superficial no ambiente urbano e rural, reconhecendo os principais componentes da morfologia das bacias e das redes hidrográficas e a sua localização no modelado da superfície terrestre e da cobertura vegetal.", "componente": "Geografia", "ano": "6º ano", "unidade": "Conexões e escalas", "objeto": "Relações entre os componentes físico-naturais", "pagina": "p. 385 (página 387 do arquivo PDF)"}, "EF06GE05": {"texto": "(EF06GE05) Relacionar padrões climáticos, tipos de solo, relevo e formações vegetais.", "componente": "Geografia", "ano": "6º ano", "unidade": "Conexões e escalas", "objeto": "Relações entre os componentes físico-naturais", "pagina": "p. 385 (página 387 do arquivo PDF)"}, "EF06GE10": {"texto": "(EF06GE10) Explicar as diferentes formas de uso do solo (rotação de terras, terraceamento, aterros etc.) e de apropriação dos recursos hídricos (sistema de irrigação, tratamento e redes de distribuição), bem como suas vantagens e desvantagens em diferentes épocas e lugares.", "componente": "Geografia", "ano": "6º ano", "unidade": "Natureza, ambientes e qualidade de vida", "objeto": "Biodiversidade e ciclo hidrológico", "pagina": "p. 385 (página 387 do arquivo PDF)"}, "EF06GE11": {"texto": "(EF06GE11) Analisar distintas interações das sociedades com a natureza, com base na distribuição dos componentes físico-naturais, incluindo as transformações da biodiversidade local e do mundo.", "componente": "Geografia", "ano": "6º ano", "unidade": "Natureza, ambientes e qualidade de vida", "objeto": "Biodiversidade e ciclo hidrológico", "pagina": "p. 385 (página 387 do arquivo PDF)"}, "EF06GE12": {"texto": "(EF06GE12) Identificar o consumo dos recursos hídricos e o uso das principais bacias hidrográficas no Brasil e no mundo, enfatizando as transformações nos ambientes urbanos.", "componente": "Geografia", "ano": "6º ano", "unidade": "Natureza, ambientes e qualidade de vida", "objeto": "Biodiversidade e ciclo hidrológico", "pagina": "p. 385 (página 387 do arquivo PDF)"}};
  const ODS = {"2": {"nome": "Fome zero e agricultura sustentável", "objetivo": "Acabar com a fome, alcançar a segurança alimentar e melhoria da nutrição e promover a agricultura sustentável", "cor": "#DDA63A", "metas": {"2.4": "Até 2030, garantir sistemas sustentáveis de produção de alimentos e implementar práticas agrícolas resilientes, que aumentem a produtividade e a produção, que ajudem a manter os ecossistemas, que fortaleçam a capacidade de adaptação às mudanças climáticas, às condições meteorológicas extremas, secas, inundações e outros desastres, e que melhorem progressivamente a qualidade da terra e do solo"}}, "4": {"nome": "Educação de qualidade", "objetivo": "Assegurar a educação inclusiva e equitativa e de qualidade, e promover oportunidades de aprendizagem ao longo da vida para todas e todos", "cor": "#C5192D", "metas": {"4.7": "Até 2030, garantir que todos os alunos adquiram conhecimentos e habilidades necessárias para promover o desenvolvimento sustentável, inclusive, entre outros, por meio da educação para o desenvolvimento sustentável e estilos de vida sustentáveis, direitos humanos, igualdade de gênero, promoção de uma cultura de paz e não violência, cidadania global e valorização da diversidade cultural e da contribuição da cultura para o desenvolvimento sustentável"}}, "6": {"nome": "Água potável e saneamento", "objetivo": "Assegurar a disponibilidade e gestão sustentável da água e saneamento para todas e todos", "cor": "#26BDE2", "metas": {"6.1": "Até 2030, alcançar o acesso universal e equitativo a água potável e segura para todos", "6.2": "Até 2030, alcançar o acesso a saneamento e higiene adequados e equitativos para todos, e acabar com a defecação a céu aberto, com especial atenção para as necessidades das mulheres e meninas e daqueles em situação de vulnerabilidade", "6.3": "Até 2030, melhorar a qualidade da água, reduzindo a poluição, eliminando despejo e minimizando a liberação de produtos químicos e materiais perigosos, reduzindo à metade a proporção de águas residuais não tratadas e aumentando substancialmente a reciclagem e reutilização segura globalmente", "6.4": "Até 2030, aumentar substancialmente a eficiência do uso da água em todos os setores e assegurar retiradas sustentáveis e o abastecimento de água doce para enfrentar a escassez de água, e reduzir substancialmente o número de pessoas que sofrem com a escassez de água", "6.5": "Até 2030, implementar a gestão integrada dos recursos hídricos em todos os níveis, inclusive via cooperação transfronteiriça, conforme apropriado", "6.6": "Até 2020, proteger e restaurar ecossistemas relacionados com a água, incluindo montanhas, florestas, zonas úmidas, rios, aquíferos e lagos", "6.a": "Até 2030, ampliar a cooperação internacional e o apoio à capacitação para os países em desenvolvimento em atividades e programas relacionados à água e saneamento, incluindo a coleta de água, a dessalinização, a eficiência no uso da água, o tratamento de efluentes, a reciclagem e as tecnologias de reuso", "6.b": "Apoiar e fortalecer a participação das comunidades locais, para melhorar a gestão da água e do saneamento"}}, "11": {"nome": "Cidades e comunidades sustentáveis", "objetivo": "Tornar as cidades e os assentamentos humanos inclusivos, seguros, resilientes e sustentáveis", "cor": "#FD9D24", "metas": {"11.5": "Até 2030, reduzir significativamente o número de mortes e o número de pessoas afetadas por catástrofes e substancialmente diminuir as perdas econômicas diretas causadas por elas em relação ao produto interno bruto global, incluindo os desastres relacionados à água, com o foco em proteger os pobres e as pessoas em situação de vulnerabilidade", "11.6": "Até 2030, reduzir o impacto ambiental negativo per capita das cidades, inclusive prestando especial atenção à qualidade do ar, gestão de resíduos municipais e outros"}}, "12": {"nome": "Consumo e produção responsáveis", "objetivo": "Assegurar padrões de produção e de consumo sustentáveis", "cor": "#BF8B2E", "metas": {"12.5": "Até 2030, reduzir substancialmente a geração de resíduos por meio da prevenção, redução, reciclagem e reuso"}}, "13": {"nome": "Ação contra a mudança global do clima", "objetivo": "Tomar medidas urgentes para combater a mudança climática e seus impactos", "cor": "#3F7E44", "metas": {"13.1": "Reforçar a resiliência e a capacidade de adaptação a riscos relacionados ao clima e às catástrofes naturais em todos os países", "13.2": "Integrar medidas da mudança do clima nas políticas, estratégias e planejamentos nacionais", "13.3": "Melhorar a educação, aumentar a conscientização e a capacidade humana e institucional sobre mitigação, adaptação, redução de impacto e alerta precoce da mudança do clima"}}, "14": {"nome": "Vida na água", "objetivo": "Conservação e uso sustentável dos oceanos, dos mares e dos recursos marinhos para o desenvolvimento sustentável", "cor": "#0A97D9", "metas": {"14.1": "Até 2025, prevenir e reduzir significativamente a poluição marinha de todos os tipos, especialmente a advinda de atividades terrestres, incluindo detritos marinhos e a poluição por nutrientes", "14.2": "Até 2020, gerir de forma sustentável e proteger os ecossistemas marinhos e costeiros para evitar impactos adversos significativos, inclusive por meio do reforço da sua capacidade de resiliência, e tomar medidas para a sua restauração, a fim de assegurar oceanos saudáveis e produtivos"}}, "15": {"nome": "Vida terrestre", "objetivo": "Proteger, recuperar e promover o uso sustentável dos ecossistemas terrestres, gerir de forma sustentável as florestas, combater a desertificação, deter e reverter a degradação da terra e deter a perda de biodiversidade", "cor": "#56C02B", "metas": {"15.1": "Até 2020, assegurar a conservação, recuperação e uso sustentável de ecossistemas terrestres e de água doce interiores e seus serviços, em especial florestas, zonas úmidas, montanhas e terras áridas, em conformidade com as obrigações decorrentes dos acordos internacionais", "15.2": "Até 2020, promover a implementação da gestão sustentável de todos os tipos de florestas, deter o desmatamento, restaurar florestas degradadas e aumentar substancialmente o florestamento e o reflorestamento globalmente", "15.3": "Até 2030, combater a desertificação, restaurar a terra e o solo degradado, incluindo terrenos afetados pela desertificação, secas e inundações, e lutar para alcançar um mundo neutro em termos de degradação do solo", "15.5": "Tomar medidas urgentes e significativas para reduzir a degradação de habitat naturais, deter a perda de biodiversidade e, até 2020, proteger e evitar a extinção de espécies ameaçadas"}}};
  const ICONE = {"2": "data:image/svg+xml;base64,", "4": "data:image/svg+xml;base64,", "6": "data:image/svg+xml;base64,", "11": "data:image/svg+xml;base64,", "12": "data:image/svg+xml;base64,", "13": "data:image/svg+xml;base64,", "14": "data:image/svg+xml;base64,", "15": "data:image/svg+xml;base64,"};
  const PARADA_ODS = {"Amazônia": [[13, ["13.3"]], [15, ["15.1", "15.2"]], [6, ["6.6"]]], "Caatinga": [[6, ["6.1", "6.4"]], [13, ["13.1"]]], "Vilas sobre a água": [[11, ["11.5"]], [13, ["13.1"]], [6, ["6.b"]]], "Pantanal": [[6, ["6.6"]], [15, ["15.1", "15.5"]]], "Cerrado": [[6, ["6.6"]], [15, ["15.1"]]], "Mata Atlântica": [[15, ["15.1", "15.2"]], [6, ["6.6"]]], "Pampa": [[6, ["6.4", "6.6"]], [2, ["2.4"]], [15, ["15.1"]]], "Oceano": [[14, ["14.1", "14.2"]], [12, ["12.5"]], [6, ["6.3"]]], "Antártica": [[13, ["13.2", "13.3"]], [14, ["14.2"]]], "Andes e Himalaia": [[13, ["13.1"]], [6, ["6.4", "6.5"]], [2, ["2.4"]]], "Desertos": [[15, ["15.3"]], [6, ["6.4"]], [13, ["13.1"]]], "Grandes Lagos": [[6, ["6.6"]], [15, ["15.1", "15.5"]]], "De volta para casa": [[6, ["6.4"]], [11, ["11.6"]], [12, ["12.5"]], [4, ["4.7"]]], "Terra dos diques": [[13, ["13.1"]], [11, ["11.5"]], [6, ["6.5"]]]};
  const REFS = ["BRASIL. Ministério da Educação. <b>Base Nacional Comum Curricular</b>. Brasília: MEC, 2018. Disponível em: <a href=\"http://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf\" target=\"_blank\" rel=\"noopener\">basenacionalcomum.mec.gov.br</a>. Acesso em: 12 out. 2026.", "BRASIL. Ministério da Educação. <b>Temas contemporâneos transversais na BNCC</b>: contexto histórico e pressupostos pedagógicos. Brasília: MEC, 2019. Disponível em: <a href=\"http://basenacionalcomum.mec.gov.br/images/implementacao/contextualizacao_temas_contemporaneos.pdf\" target=\"_blank\" rel=\"noopener\">basenacionalcomum.mec.gov.br</a>. Acesso em: 12 out. 2026.", "NAÇÕES UNIDAS. <b>Transformando nosso mundo</b>: a Agenda 2030 para o Desenvolvimento Sustentável. Brasília: Nações Unidas no Brasil, 2015. Disponível em: <a href=\"https://brasil.un.org/pt-br/91863-agenda-2030-para-o-desenvolvimento-sustent%C3%A1vel\" target=\"_blank\" rel=\"noopener\">brasil.un.org</a>. Acesso em: 12 out. 2026.", "NAÇÕES UNIDAS NO BRASIL. <b>Objetivos de Desenvolvimento Sustentável</b>. Brasília: ONU Brasil, [2026]. Disponível em: <a href=\"https://brasil.un.org/pt-br/sdgs\" target=\"_blank\" rel=\"noopener\">brasil.un.org/pt-br/sdgs</a>. Acesso em: 12 out. 2026.", "UNITED NATIONS. <b>Guidelines for the use of the SDG logo including the colour wheel and 17 icons</b>. New York: United Nations, Sept. 2023. Disponível em: <a href=\"https://www.un.org/sustainabledevelopment/wp-content/uploads/2023/09/E_SDG_Guidelines_Sep20238.pdf\" target=\"_blank\" rel=\"noopener\">un.org</a>. Acesso em: 12 out. 2026."];
  const box = document.querySelector('#t-educ .educ-box'); if (!box) return;
  const fechar = '<div class="acoes" style="margin-top:14px"><button class="btn azul educ-fechar">Fechar</button></div>';
  const mc = document.getElementById('modal-c'), mw = document.getElementById('modal');
  const abre = html => { mc.innerHTML = html; mw.hidden = false; const f = mc.querySelector('.educ-fechar'); f.onclick = () => { mw.hidden = true; }; f.focus(); };
  const linhas = [...box.querySelectorAll('tbody tr')];
  const th = box.querySelector('thead tr'); const thO = document.createElement('th'); thO.textContent = 'ODS'; th.insertBefore(thO, th.children[3]);
  linhas.forEach(tr => {
    const nome = tr.children[0].textContent.trim(), lista = PARADA_ODS[nome] || [];
    const td = document.createElement('td'); td.className = 'ods-cel';
    td.innerHTML = lista.map(([n, metas]) => `<button class="ods-ic" data-n="${n}" data-metas="${metas.join(',')}" data-parada="${nome}" title="ODS ${n}: ${ODS[n].nome}"><img src="${ICONE[n]}" alt="ODS ${n}: ${ODS[n].nome}" width="64" height="64"></button>`).join('');
    tr.insertBefore(td, tr.children[3]);
    tr.querySelectorAll('.bncc').forEach(sp => { const b = document.createElement('button'); b.className = 'bncc'; b.textContent = sp.textContent; b.title = 'Ver o texto da BNCC'; sp.replaceWith(b); });
  });
  box.addEventListener('click', e => {
    const b = e.target.closest('button.bncc');
    if (b) {
      const h = BNCC[b.textContent.trim()]; if (!h) return;
      abre(`<div class="janela-educ"><span class="bncc grande">${b.textContent.trim()}</span>
        <p class="meta-educ">${h.componente} · ${h.ano}</p>
        <p><b>Unidade temática:</b> ${h.unidade}<br><b>Objeto de conhecimento:</b> ${h.objeto}</p>
        <blockquote>${h.texto}</blockquote>
        <p class="fonte-educ">Fonte: BRASIL. Ministério da Educação. Base Nacional Comum Curricular. Brasília: MEC, 2018, ${h.pagina.replace(/ \(.*\)/, '')}.</p>${fechar}</div>`);
      return;
    }
    const o = e.target.closest('.ods-ic');
    if (o) {
      const n = o.dataset.n, d = ODS[n], metas = o.dataset.metas.split(',').filter(Boolean);
      abre(`<div class="janela-educ"><div class="ods-topo"><img src="${ICONE[n]}" alt="ODS ${n}: ${d.nome}" width="110" height="110"><div><p class="meta-educ">Objetivo de Desenvolvimento Sustentável ${n}</p><h3 style="color:${d.cor}">${d.nome}</h3><p>${d.objetivo}.</p></div></div>
        <p><b>Metas ligadas à parada ${o.dataset.parada}:</b></p>
        <ul class="metas-educ">${metas.map(m => `<li><b>${m}</b> ${d.metas[m]}.</li>`).join('')}</ul>
        <p class="fonte-educ">Fonte: Nações Unidas no Brasil, Objetivos de Desenvolvimento Sustentável (brasil.un.org/pt-br/sdgs).</p>${fechar}</div>`);
    }
  });
  const nota = box.querySelector('.nota-educ');
  if (nota) nota.innerHTML = 'Competências gerais 2 (pensamento científico), 7 (argumentação com base em fatos) e 10 (agir de forma responsável e sustentável). <b>Toque no código de uma habilidade</b> para ler o texto oficial da BNCC e <b>toque no ícone de um ODS</b> para ver o objetivo e as metas da Agenda 2030 ligadas àquela parada.';
  const ref = document.createElement('div'); ref.className = 'refs-educ';
  ref.innerHTML = `<h3>Referências</h3><ol>${REFS.map(r => `<li>${r}</li>`).join('')}</ol><p class="nota-educ">Os ícones dos ODS são das Nações Unidas e foram usados com fins informativos, conforme as diretrizes da ONU, sem alteração. Seu uso não significa endosso da ONU às atividades da ANAP.</p>`;
  (nota || box.lastElementChild).after(ref);
})();
